export function getHardcodedCityData(): Record<string, Record<string, CityStatus[]>> {
  const expanded: Record<string, Record<string, CityStatus[]>> = {};
  for (const [city, invs] of Object.entries(RAW_DATA)) {
    expanded[city] = {};
    for (const [inv, rows] of Object.entries(invs)) {
      expanded[city][inv] = rows.map(([day, p10, p50, p90]) => ({
        day,
        city,
        active_cases_p10: p10,
        active_cases_p50: p50,
        active_cases_p90: p90,
      }));
    }
  }
  return expanded;
}
